<?php
require __DIR__.'/bootstrap.php';
requireAuth();
$stats=['products'=>0,'active'=>0,'drafts'=>0,'low_stock'=>0,'collections'=>0,'images'=>0,'variants'=>0,'admins'=>0];$recent=[];$dbError=false;
try{
 $pdo=db();
 $stats['products']=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();
 $stats['active']=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE status='active'")->fetchColumn();
 $stats['drafts']=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE status='draft'")->fetchColumn();
 $stats['low_stock']=(int)$pdo->query("SELECT COUNT(*) FROM product_variants WHERE is_active=1 AND availability_mode='stock' AND stock_qty BETWEEN 0 AND 3")->fetchColumn();
 $stats['collections']=(int)$pdo->query('SELECT COUNT(*) FROM collections WHERE is_active=1')->fetchColumn();
 $stats['images']=(int)$pdo->query('SELECT COUNT(*) FROM product_images')->fetchColumn();
 $stats['variants']=(int)$pdo->query('SELECT COUNT(*) FROM product_variants')->fetchColumn();
 if(canManageUsers())$stats['admins']=(int)$pdo->query('SELECT COUNT(*) FROM admin_users WHERE is_active=1')->fetchColumn();
 if(canViewAudit())$recent=$pdo->query('SELECT action,entity_type,created_at FROM admin_audit_log ORDER BY created_at DESC LIMIT 10')->fetchAll();
}catch(Throwable $e){error_log('InYou admin dashboard: '.$e->getMessage());$dbError=true;}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel · InYou</title><link rel="stylesheet" href="/admin/style.css"><style>.quick{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}.quick a{display:block;background:#fff;border:1px solid #e5e2db;border-radius:10px;padding:18px;text-decoration:none;color:#20211f}.quick strong{display:block;margin-bottom:6px}.quick small{color:#777}.role-note{display:inline-block;margin-left:8px;padding:4px 8px;border-radius:999px;background:#f1f0eb;font-size:12px;color:#666}@media(max-width:800px){.quick{grid-template-columns:1fr}}.fashion-dashboard-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0 26px}.fashion-admin .quick a{border-radius:17px;padding:23px;min-height:116px;box-shadow:0 10px 32px rgba(40,23,20,.035);transition:transform .2s}.fashion-admin .quick a:hover{transform:translateY(-3px);border-color:#dac6c2}.fashion-admin .quick strong{font-size:17px}.fashion-admin .quick small{display:block;line-height:1.55;font-size:12px}.fashion-admin .cards article{border-radius:17px;min-height:135px}.fashion-admin .cards article:first-child{background:#e8f2ec}.fashion-admin .cards article:nth-child(2){background:#f4ede5}.fashion-admin .cards article:nth-child(3){background:#f7e7e5}.fashion-admin .cards article:nth-child(4){background:#eee9f0}@media(max-width:700px){.fashion-dashboard-actions{display:grid;grid-template-columns:1fr 1fr}.fashion-dashboard-actions .catalog-new-btn{grid-column:1/-1}.fashion-dashboard-actions .admin-ghost-action{text-align:center}}</style></head><body class="dashboard fashion-admin"><?php adminSidebar('home');?><main class="content"><header><div>Hola, <?=h($_SESSION['admin_name']??'Administrador')?> <span class="role-note"><?=h(role())?></span></div><form method="post" action="/admin/logout.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="signout">Cerrar sesión</button></form></header><div class="eyebrow">PANEL DE TU TIENDA</div><h1>Tu tienda, de un vistazo</h1><p>Lo importante para organizar tus prendas y mantener el catálogo al día.</p><div class="fashion-dashboard-actions"><a href="/admin/products.php?new=1" class="catalog-new-btn">＋ Cargar nueva prenda</a><a href="/admin/products.php?estado=draft" class="admin-ghost-action">Ver borradores →</a><a href="/" target="_blank" rel="noopener" class="admin-ghost-action">Ver tienda ↗</a></div><?php if($dbError):?><div class="error">No se pudo cargar toda la información. Revisá la conexión y la estructura de la base.</div><?php endif;?><section class="cards"><article><small>Productos activos</small><strong><?=h((string)$stats['active'])?></strong></article><article><small>Talles y colores registrados</small><strong><?=h((string)$stats['variants'])?></strong></article><article><small>Variantes con stock bajo (0–3)</small><strong><?=h((string)$stats['low_stock'])?></strong></article><article><small>Colecciones activas</small><strong><?=h((string)$stats['collections'])?></strong></article></section><section class="quick"><a href="/admin/products.php"><strong>Prendas y productos</strong><small>Cargá fotos, precios, talles y publicá en la tienda.</small></a><a href="/admin/inventory.php"><strong>Control de stock</strong><small>Revisá disponibilidad por talle y color.</small></a><a href="/admin/collections.php"><strong>Colecciones</strong><small>Organización del catálogo público.</small></a><a href="/admin/media.php"><strong>Fotografías</strong><small>Revisá las imágenes de tu catálogo.</small></a><?php if(canManageSettings()):?><a href="/admin/settings.php"><strong>Configuración</strong><small>Tienda, WhatsApp y activación comercial.</small></a><?php endif;?><?php if(canViewAudit()):?><a href="/admin/audit.php"><strong>Actividad</strong><small>Consultá qué se modificó en la tienda.</small></a><?php endif;?><?php if(canManageUsers()):?><a href="/admin/users.php"><strong>Usuarios</strong><small>Accesos individuales, roles y contraseñas.</small></a><?php endif;?><a href="/" target="_blank" rel="noopener"><strong>Ver tienda</strong><small>Abrir catálogo público en otra pestaña.</small></a></section><section class="panels"><article><h2>Catálogo</h2><p><?=h((string)$stats['products'])?> productos · <?=h((string)$stats['images'])?> imágenes · <?=h((string)$stats['drafts'])?> borradores.</p><div class="empty"><p>El panel administra el catálogo aprobado sin habilitar operaciones financieras.</p><a href="/admin/products.php">Gestionar catálogo →</a></div></article><?php if(canViewAudit()):?><article><h2>Actividad reciente</h2><?php if(!$recent):?><div class="empty">Todavía no hay actividad registrada.</div><?php else:?><ul><?php foreach($recent as $r):?><li><?=h($r['action'])?> · <?=h($r['entity_type'])?> <small><?=h($r['created_at'])?></small></li><?php endforeach;?></ul><?php endif;?></article><?php endif;?></section><p class="notice">Administración del catálogo · Los pedidos y pagos no se gestionan desde este panel.</p></main></body></html>